  outputAddr <= Scheduler_outputAddr;

  inputAddr <= Scheduler_inputAddr;

  inputSize <= Scheduler_inputSize;

  outputSize <= Scheduler_outputSize;

  FrameStartCount <= FrameStartCount_tmp;

  FrameEndCount <= FrameEndCount_tmp;

END rtl;

